#include <iostream>
#include <cstddef>

int main() {
    const std::size_t ARRAY_SIZE = 4;
    int b[ARRAY_SIZE] = {10, 20, 30, 40};
    int* bPtr = b;

    std::cout << "Array index notation:\n";
    for (std::size_t i = 0; i < ARRAY_SIZE; ++i) {
        std::cout << "b[" << i << "] = " << b[i] << "\n";
    }

    std::cout << "\nPointer/offset notation with array name:\n";
    for (std::size_t offset = 0; offset < ARRAY_SIZE; ++offset) {
        std::cout << "*(b + " << offset << ") = " << *(b + offset) << "\n";
    }

    std::cout << "\nPointer index notation:\n";
    for (std::size_t i = 0; i < ARRAY_SIZE; ++i) {
        std::cout << "bPtr[" << i << "] = " << bPtr[i] << "\n";
    }

    std::cout << "\nPointer/offset notation with pointer:\n";
    for (std::size_t offset = 0; offset < ARRAY_SIZE; ++offset) {
        std::cout << "*(bPtr + " << offset << ") = " << *(bPtr + offset) << "\n";
    }

    return 0;
}

